+        "a","an","the","and","or","but","if","in","on","at","to","for",
+        "of","with","by","is","are","was","were","be","been","being",
+        "have","has","had","do","does","did","will","would","shall",
+        "should","may","might","can","could","this","that","these",
+        "those","it","its","i","you","he","she","we","they","me",
+        "him","her","us","them","my","your","his","our","their","not",
+        "no","so","as","from","about","into","than","then","also"
+    };
+
+    public string Summarize(string text, int maxSentences)
+    {
+        var sentences = SplitSentences(text);
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        var wordFrequencies = ComputeWordFrequencies(sentences);
+        var scored = ScoreSentences(sentences, wordFrequencies);
+
+        // Pick top sentences but preserve original order
+        var topIndices = scored
+            .OrderByDescending(s => s.Score)
+            .Take(maxSentences)
+            .Select(s => s.Index)
+            .OrderBy(i => i)
+            .ToList();
+
+        return string.Join(" ", topIndices.Select(i => sentences[i]));
+    }
+
+    private static List<string> SplitSentences(string text)
+    {
+        // Split on sentence-ending punctuation followed by whitespace or end-of-string
+        var raw = System.Text.RegularExpressions.Regex
+            .Split(text, @"(?<=[.!?])\s+");
+
+        return raw
+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+    }
+
+    private static Dictionary<string, int> ComputeWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in Tokenize(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    freq[word] = freq.GetValueOrDefault(word) + 1;
+            }
+        }
+        return freq;
+    }
+
+    private static List<(int Index, double Score)> ScoreSentences(
+        List<string> sentences, Dictionary<string, int> wordFrequencies)
+    {
+        var scored = new List<(int Index, double Score)>();
+        for (int i = 0; i < sentences.Count; i++)
+        {
+            var words = Tokenize(sentences[i]);
+            double score = words
+                .Where(w => !StopWords.Contains(w))
+                .Sum(w => wordFrequencies.GetValueOrDefault(w));
+
+            // Normalise by word count to avoid bias toward long sentences
+            if (words.Count > 0)
+                score /= words.Count;
+
+            scored.Add((i, score));
+        }
+        return scored;
+    }
+
+    private static List<string> Tokenize(string text) =>
+        System.Text.RegularExpressions.Regex
+            .Matches(text, @"\w+")
+            .Select(m => m.Value)
+            .ToList();
+}
